<?php
declare(strict_types=1);

const LC_ROOT = __DIR__ . '/..';
foreach ([LC_ROOT.'/.env', dirname(LC_ROOT).'/.env'] as $env) if (is_file($env)) foreach (file($env, FILE_IGNORE_NEW_LINES) as $line) if (preg_match('/^([A-Z][A-Z0-9_]*)=(.*)$/', trim($line), $m) && getenv($m[1])===false) putenv($m[1].'='.trim(trim($m[2]), "\"'"));
function lc_env(string $key,string $default=''): string { $value=getenv($key); return $value===false||$value===''?$default:$value; }
function lc_db(): PDO { static $db; if(!$db){$path=lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite'); if(!is_dir(dirname($path))) mkdir(dirname($path),0700,true); $db=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $db->exec('PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000');} return $db; }
function q(string $sql,array $args=[]): PDOStatement{$s=lc_db()->prepare($sql);$s->execute($args);return $s;}
function one(string $sql,array $args=[]):?array{return q($sql,$args)->fetch()?:null;}
function esc(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function csrf():string{if(session_status()!==PHP_SESSION_ACTIVE)session_start();return $_SESSION['csrf']??=bin2hex(random_bytes(24));}
function require_csrf():void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid request token');}
function setup():void{lc_db()->exec("CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS themes(id INTEGER PRIMARY KEY,name TEXT NOT NULL,locale TEXT NOT NULL DEFAULT 'global',payload TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL CHECK(status IN('draft','published')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS licenses(id INTEGER PRIMARY KEY,product TEXT NOT NULL DEFAULT 'transport-cms',key_hash TEXT NOT NULL,key_hint TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','revoked')),domain_limit INTEGER NOT NULL DEFAULT 1,theme_id INTEGER REFERENCES themes(id) ON DELETE SET NULL,source TEXT NOT NULL DEFAULT 'manual',purchase_code_hash TEXT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS domains(id INTEGER PRIMARY KEY,license_id INTEGER NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,domain TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT,UNIQUE(license_id,domain)); CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,license_id INTEGER REFERENCES licenses(id) ON DELETE SET NULL,action TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS purchase_requests(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,company TEXT NOT NULL DEFAULT '',message TEXT NOT NULL DEFAULT '',product TEXT NOT NULL DEFAULT 'transport-cms',status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','contacted','completed','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");}
function host(string $value):string{$value=strtolower(trim($value));$value=preg_replace('#^https?://#','',$value);$value=explode('/',$value,2)[0];$value=preg_replace('/:\d+$/','',$value);if(!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$value))throw new RuntimeException('A valid public domain is required.');return $value;}
function key_parts(string $key):array{if(!preg_match('/^TDL-([0-9]+)-([A-Z0-9]{24})$/',strtoupper(trim($key)),$m))throw new RuntimeException('Invalid licence key format.');return [(int)$m[1],strtoupper($m[2])];}
function issue_key():array{$secret=strtoupper(bin2hex(random_bytes(12)));$id=(int)lc_db()->lastInsertId();return [$id,'TDL-'.$id.'-'.$secret,$secret];}
function api_json():array{$raw=file_get_contents('php://input')?:'';$json=json_decode($raw,true);return is_array($json)?$json:$_POST;}
function reply(array $data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($data,JSON_UNESCAPED_SLASHES);exit;}
function licence_api(bool $activate):never{try{$input=api_json();[$id,$secret]=key_parts((string)($input['license_key']??''));$licence=one('SELECT * FROM licenses WHERE id=?',[$id]);if(!$licence||!password_verify($secret,$licence['key_hash'])||$licence['status']!=='active')throw new RuntimeException('Licence is not active.');$domain=host((string)($input['domain']??''));$bound=one('SELECT id FROM domains WHERE license_id=? AND domain=?',[$id,$domain]);if(!$bound){$count=(int)(one('SELECT count(*) count FROM domains WHERE license_id=?',[$id])['count']??0);if(!$activate||$count>=(int)$licence['domain_limit'])throw new RuntimeException('This domain is not permitted for the licence.');q('INSERT INTO domains(license_id,domain,last_seen_at) VALUES(?,?,datetime(\'now\'))',[$id,$domain]);q('INSERT INTO events(license_id,action,detail) VALUES(?,?,?)',[$id,'domain.activated',$domain]);}else q('UPDATE domains SET last_seen_at=datetime(\'now\') WHERE id=?',[$bound['id']]);$locale=preg_replace('/[^a-z-]/','',strtolower((string)($input['locale']??'global')));$theme=one("SELECT name,locale,payload FROM themes WHERE id=? AND status='published' AND locale IN (?, 'global') ORDER BY locale=? DESC LIMIT 1",[$licence['theme_id'],$locale,$locale]);reply(['active'=>true,'license'=>['product'=>$licence['product'],'domain'=>$domain,'domain_limit'=>(int)$licence['domain_limit']],'theme'=>$theme?['name'=>$theme['name'],'locale'=>$theme['locale'],'payload'=>json_decode($theme['payload'],true)]:null,'checked_at'=>gmdate('c')]);}catch(Throwable $e){reply(['active'=>false,'error'=>$e->getMessage()],422);}}
function logged_in():bool{return !empty($_SESSION['admin']);}
function login_required():void{if(!logged_in()){header('Location: ./login');exit;}}
