px}.actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}.button{display:inline-flex;align-items:center;gap:8px;padding:13px 19px;border-radius:9px;background:var(--orange);font-weight:800;color:#173342}.button.ghost{color:white;background:#ffffff14;border:1px solid #ffffff55}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:white;border:1px solid var(--line);padding:25px;border-radius:15px;box-shadow:0 8px 26px #08283a0a}.card h2{font:800 23px Manrope;margin:0 0 9px;letter-spacing:-.5px}.card p{color:var(--muted);margin:0}.feature-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:11px;color:#d75009;background:#fff0e6;font-size:21px;margin-bottom:18px}.theme-card{min-height:200px;position:relative;overflow:hidden;background:linear-gradient(140deg,#103547,#287187);color:white;border:0}.theme-card:nth-child(2){background:linear-gradient(140deg,#3b2b56,#af6b58)}.theme-card:nth-child(3){background:linear-gradient(140deg,#233b31,#7b9b68)}.theme-card p{color:#e2ecee}.theme-tag{display:inline-block;background:#ffffff22;border:1px solid #ffffff44;border-radius:20px;padding:4px 9px;font-size:12px;margin-bottom:45px}form.card{max-width:700px;margin:44px auto}label{font-weight:700;font-size:14px;display:block;margin-top:13px}input,textarea,select{font:inherit;width:100%;padding:13px;margin-top:5px;border:1px solid #ccd8dc;border-radius:8px;background:white}textarea{min-height:130px}button{cursor:pointer;border:0;border-radius:8px;background:var(--orange);color:#123342;font-weight:800;padding:13px 18px;margin-top:16px}table{width:100%;border-collapse:collapse}td,th{padding:11px;text-align:left;border-bottom:1px solid var(--line)}.section-title{font:800 31px Manrope;margin:50px 0 18px;letter-spacing:-1px}.site-foot{background:#061f2d;color:#d1e0e5;padding:35px 24px;text-align:center;font-size:14px}@media(max-width:760px){.nav{height:68px;padding:0 18px;gap:13px}.brand{font-size:19px}.nav>a:not(.nav-cta){display:none}.shell{padding:0 16px 42px}.hero{padding:42px 26px;margin:18px 0}.hero h1{letter-spacing:-1px}.hero p{font-size:16px}.grid{grid-template-columns:1fr}.section-title{font-size:27px}.card{padding:21px}}</style><header class="site-head"><nav class="nav"><a class="brand" href="./shop">TOFI<b>DESK</b> <span>Transportation</span></a>'.$nav.'</nav></header><main class="shell">'.$body.'</main><footer class="site-foot">© '.date('Y').' TofiDesk Transportation · Licensed software for transport businesses</footer></html>';exit;}
setup();$sessionPath=dirname(lc_env('LICENSE_DB_PATH',LC_ROOT.'/storage/licenses.sqlite')).'/sessions';if(!is_dir($sessionPath))mkdir($sessionPath,0700,true);session_save_path($sessionPath);session_start();$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$script=$_SERVER['SCRIPT_NAME']??'/index.php';$base=str_ends_with($script,'/index.php')?rtrim(dirname($script),'/'):'';if($base!==''&&$base!=='/'&&str_starts_with($path,$base))$path=substr($path,strlen($base))?:'/';
if($path==='/api/v1/licenses/activate')licence_api(true);if($path==='/api/v1/licenses/check')licence_api(false);
if($path==='/shop'){ $themes=q("SELECT name,locale FROM themes WHERE status='published' ORDER BY id DESC LIMIT 3")->fetchAll(); $cards='';foreach($themes?:[['name'=>'Mediterranean Route','locale'=>'global'],['name'=>'Urban Freight','locale'=>'en'],['name'=>'Nordic Move','locale'=>'global']] as $theme)$cards.='<article class="card theme-card"><span class="theme-tag">'.esc($theme['locale']==='global'?'All languages':strtoupper($theme['locale'])).'</span><h2>'.esc($theme['name']).'</h2><p>Ready to publish through a licence-controlled delivery channel.</p></article>';layout('Transport CMS','<section class="hero"><span class="eyebrow">Transport business platform</span><h1>Sell transport websites with confidence.</h1><p>One polished CMS for local movers, logistics teams and international transport brands. Built-in multilingual pages, quotation workflows, theme delivery and domain licensing.</p><div class="actions"><a class="button" href="./contact">Buy Transport CMS →</a><a class="button ghost" href="#themes">Explore themes</a></div></section><section class="grid"><article class="card"><div class="feature-icon">◈</div><h2>14 languages</h2><p>Public site, content and RTL support for global transport businesses.</p></article><article class="card"><div class="feature-icon">⌘</div><h2>Licence control</h2><p>Bind each purchase to approved customer domains from one centre.</p></article><article class="card"><div class="feature-icon">✦</div><h2>Theme delivery</h2><p>Publish safe branded themes to eligible installations.</p></article></section><h2 id="themes" class="section-title">Themes made for transport brands</h2><section class="grid">'.$cards.'</section><section class="card" style="margin-top:24px"><h2>Everything after purchase stays organised.</h2><p>Your buyer activates their licence, connects the domain and receives the assigned design from the product’s administration panel. Support and purchase requests remain visible in one secure place.</p></section>',true); }
if($path==='/contact'){ $notice=''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$name=trim((string)($_POST['name']??''));$email=filter_var(trim((string)($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$company=mb_substr(trim((string)($_POST['company']??'')),0,160);$message=mb_substr(trim((string)($_POST['message']??'')),0,3000);if($name===''||!$email)throw new RuntimeException('Name and a valid email are required.');q('INSERT INTO purchase_requests(name,email,company,message) VALUES(?,?,?,?)',[$name,$email,$company,$message]);$notice='<div class="card"><h2>Request received</h2><p>We will reply to your email with purchasing and licence setup details.</p></div>'; } layout('Contact and purchase',$notice.'<form class="card" method="post"><span class="eyebrow">Transport CMS</span><h2>Request purchase or a product demo</h2><p>Tell us where you plan to use the platform. We will help you select a licence and theme.</p><input type="hidden" name="csrf" value="'.csrf().'"><label>Name<input name="name" required placeholder="Your name"></label><label>Email<input type="email" name="email" required placeholder="you@company.com"></label><label>Company<input name="company" placeholder="Company name"></label><label>Message<textarea name="message" placeholder="Domain, preferred language, theme or support request"></textarea></label><button>Send purchase request →</button></form>',true); }
if($path==='/install'){if(one('SELECT id FROM admins'))layout('Already installed','<div class="card">Installation is locked.</div>');if(!hash_equals(lc_env('LICENSE_INSTALL_TOKEN'),(string)($_GET['token']??'')))reply(['error'=>'Not found'],404);if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');if(!$email||strlen($password)<12)throw new RuntimeException('Use a valid email and 12+ character password.');q('INSERT INTO admins(email,password_hash) VALUES(?,?)',[$email,password_hash($password,PASSWORD_DEFAULT)]);header('Location: ./login');exit;}layout('Install','<form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>First administrator</h2><input name="email" type="email" required placeholder="Email"><input name="password" type="password" minlength="12" required placeholder="Password"><button>Create administrator</button></form>');}
if($path==='/login'){if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$a=one('SELECT * FROM admins WHERE email=?',[strtolower(trim($_POST['email']??''))]);if($a&&password_verify((string)($_POST['password']??''),$a['password_hash'])){$_SESSION['admin']=$a['id'];header('Location: ./');exit;}}layout('Sign in','<form class="card" method="post"><input type="hidden" name="csrf" value="'.csrf().'"><h2>Administrator sign in</h2><input name="email" type="email" required><input name="password" type="password" required><button>Sign in</button></form>');}
if($path==='/logout'){session_destroy();header('Location: ./login');exit;}login_required();
if($path==='/themes'&&$_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$payload=json_decode((string)($_POST['payload']??''),true);if(!is_array($payload))throw new RuntimeException('Theme payload must be JSON.');q('INSERT INTO themes(name,locale,payload,status) VALUES(?,?,?,?)',[trim($_POST['name']??''),$_POST['locale']??'global',json_encode($payload),$_POST['status']??'draft']);header('Location: ./themes');exit;}
if($path==='/licenses'&&$_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$theme=(int)($_POST['theme_id']??0)?:null;$limit=max(1,min(50,(int)($_POST['domain_limit']??1)));$pending='pending-'.bin2hex(random_bytes(8));q('INSERT INTO licenses(product,key_hash,key_hint,status,domain_limit,theme_id,source) VALUES(?,?,?,?,?,?,?)',['transport-cms','pending',$pending,'active',$limit,$theme,'manual']);[$id,$key,$secret]=issue_key();q('UPDATE licenses SET key_hash=?,key_hint=? WHERE id=?',[password_hash($secret,PASSWORD_DEFAULT),'TDL-'.$id,$id]);$_SESSION['issued_key']=$key;header('Location: ./licenses');exit;}
if($path==='/themes'){$themes=q('SELECT * FROM themes ORDER BY id DESC')->fetchAll();$rows='';foreach($themes as $t)$rows.='<tr><td>'.esc($t['name']).'</td><td>'.esc($t['locale']).'</td><td>'.esc($t['status']).'</td></tr>';layout('Themes','<div class="card"><h2>Publishable themes</h2><p>Only published theme payloads are returned to licensed installations. Payload can contain colours, logo/media URLs and section settings; never include executable PHP.</p><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><input name="name" required placeholder="Theme name"><select name="locale"><option value="global">All languages</option><option>tr</option><option>en</option><option>de</option><option>fr</option><option>es</option><option>it</option><option>pt</option><option>nl</option><option>ru</option><option>ar</option><option>zh</option><option>ja</option><option>ko</option><option>fa</option></select><select name="status"><option value="draft">Draft</option><option value="published">Published</option></select><textarea name="payload" required>{"primary_color":"#0D2E42","accent_color":"#FF9149"}</textarea><button>Save theme</button></form></div><div class="card"><table><tr><th>Name</th><th>Locale</th><th>Status</th></tr>'.$rows.'</table></div>');}
if($path==='/licenses'){$themes=q("SELECT id,name FROM themes WHERE status='published' ORDER BY name")->fetchAll();$opts='<option value="">No remote theme</option>';foreach($themes as $t)$opts.='<option value="'.$t['id'].'">'.esc($t['name']).'</option>';$rows='';foreach(q('SELECT l.*,group_concat(d.domain,\', \') domains FROM licenses l LEFT JOIN domains d ON d.license_id=l.id GROUP BY l.id ORDER BY l.id DESC')->fetchAll() as $l)$rows.='<tr><td>'.esc($l['key_hint']).'…</td><td>'.esc($l['status']).'</td><td>'.esc($l['domains']??'—').'</td><td>'.(int)$l['domain_limit'].'</td></tr>';$notice=isset($_SESSION['issued_key'])?'<div class="card"><strong>New licence key — show once:</strong><code>'.esc($_SESSION['issued_key']).'</code></div>':'';unset($_SESSION['issued_key']);$requests='';foreach(q('SELECT * FROM purchase_requests ORDER BY id DESC LIMIT 50')->fetchAll() as $request)$requests.='<tr><td>'.esc($request['name']).'<br><small>'.esc($request['email']).'</small></td><td>'.esc($request['company']).'</td><td>'.esc($request['message']).'</td><td>'.esc($request['status']).'</td></tr>';layout('Licences',$notice.'<div class="card"><h2>Create licence</h2><form method="post"><input type="hidden" name="csrf" value="'.csrf().'"><label>Allowed domains</label><input type="number" name="domain_limit" value="1" min="1" max="50"><label>Published remote theme</label><select name="theme_id">'.$opts.'</select><button>Create key</button></form></div><div class="card"><table><tr><th>Key</th><th>Status</th><th>Domains</th><th>Limit</th></tr>'.$rows.'</table></div><div class="card"><h2>Purchase requests</h2><table><tr><th>Buyer</th><th>Company</th><th>Message</th><th>Status</th></tr>'.$requests.'</table></div>');}
